241	/// The APNs body, built from the shared protocol definition so the sender's padding
242	/// arithmetic is computed against exactly these bytes.
243	fn build_envelope(kid: u32, enc: &str, ct: &str) -> serde_json::Value {
244	    crate::protocol::apns_envelope(kid, enc, ct)
245	}
