260	/// Mint an APNs provider token: an ES256 JWS over `{iss: team_id, iat}` with the key id in
261	/// the header. Apple wants no `exp` — the token's age *is* its expiry, which is why the
262	/// cache refreshes on a timer rather than on a claim.
263	fn sign_jwt(key: &SigningKey, key_id: &str, team_id: &str, issued_at: u64) -> String {
264	    // Built through serde rather than string interpolation: `key_id`/`team_id` are
265	    // operator-supplied, and a stray quote in either would otherwise emit a JWT that is
266	    // not JSON at all.
267	    let header = serde_json::json!({ "alg": "ES256", "kid": key_id });
268	    let claims = serde_json::json!({ "iss": team_id, "iat": issued_at });
269	    let signing_input = format!(
270	        "{}.{}",
271	        b64url(header.to_string().as_bytes()),
272	        b64url(claims.to_string().as_bytes())
273	    );
274	    // ES256's signature encoding is the raw r‖s pair, which is precisely what
275	    // `Signature::to_bytes` produces — no DER to unwrap.
276	    let signature: Signature = key.sign(signing_input.as_bytes());
277	    format!("{signing_input}.{}", b64url(&signature.to_bytes()))
